ACTUAL="$(sha256sum "$ZIP" | awk '{print $1}')"
[[ "$ACTUAL" == "$EXPECTED_ZIP_SHA256" ]] || die "embedded ZIP SHA mismatch: $ACTUAL"
python3 - "$ZIP" "$TMP" <<'PY'
import sys,zipfile
z,d=sys.argv[1:]
with zipfile.ZipFile(z) as f:
    bad=f.testzip()
    if bad: raise SystemExit('ZIP CRC fail: '+bad)
    names=f.namelist()
    if not names or any(n.startswith('/') or '..' in n.split('/') for n in names): raise SystemExit('unsafe ZIP path')
    f.extractall(d)
print('ZIP_CRC_AND_PATHS=PASS')
PY
[[ -d "$SRC" ]] || die "source root nova3000 없음"
( cd "$SRC" && sha256sum -c SOURCE_MANIFEST.sha256 >/dev/null ) || die "SOURCE_MANIFEST 검증 실패"
echo "SOURCE_MANIFEST=PASS"

say "2/15 Ground-up contract preflight"
python3 - "$SRC" <<'PY'
from pathlib import Path
import json,sys
r=Path(sys.argv[1])
assert (r/'Dockerfile').read_text().startswith('FROM python:3.12-slim-bookworm')
text='\n'.join(p.read_text(errors='ignore') for p in list((r/'app').rglob('*.py'))+list((r/'static').rglob('*')) if p.is_file())
for bad in ('docker commit','main.py.bak','ROOT-MEMORY-LIVENESS','CLEAN-RUNTIME-R1.'):
    assert bad not in text,bad
j=json.loads((r/'SIGNAL_POLICY_FROZEN.json').read_text())
assert j['policy']=='ENTRY_V18_TRUTH_GUARD_MAX_PROFIT'
assert j['pressure_score']==62 and j['direct']['score']==75 and j['cooldown_sec']==600
ws=(r/'app/broker/websocket.py').read_text(); kw=(r/'app/broker/kiwoom.py').read_text(); cfg=(r/'app/config.py').read_text()
assert "'trnm':'REMOVE'" in ws and '_remove_group' in ws and "'refresh':'1'" in ws
assert 'removed=sorted(old_set-new_set)' in ws and 'added=[x for x in items if x not in old_set]' in ws
