sudo docker exec -i "$CANDIDATE" python - <<'PY'
import json,os,time,urllib.request
TOKEN=os.getenv('APP_ACCESS_TOKEN','').strip()
def get(path):
    h={'X-App-Token':TOKEN} if TOKEN else {}
    with urllib.request.urlopen(urllib.request.Request('http://127.0.0.1:8000'+path,headers=h),timeout=3) as r:return json.load(r)
rss=[]
for i in range(30):
    j=get('/api/realtime-health');m=j.get('memory') or {};t=j.get('telemetry') or {};w=j.get('journal') or {}
    assert j.get('ok'),j
