    assert int(j.get('coalesce_errors') or 0)==0,j.get('coalesce_errors')
    rss.append(float(m.get('rss_mb') or 0));time.sleep(2)
print('CANDIDATE_SOAK=PASS',{'rss_start':rss[0],'rss_end':rss[-1],'rss_max':max(rss)})
